                if table == "checks_notes" and action == "update" and row_id is not None and "status" in body:
                    current_status = scalar(conn, "SELECT status FROM checks_notes WHERE id=?", (row_id,))
                    if current_status is not None and str(current_status) != str(body.get("status") or ""):
                        return self.send_json({"error": "Use the check or note status workflow"}, 409)
                if table == "subcontractors":
                    existing_columns = set(table_columns(conn, table))
                    for column, ddl in (
                        ("payment_model", "TEXT DEFAULT 'fixed'"),
                        ("currency", "TEXT DEFAULT 'TRY'"),
                        ("phone", "TEXT"),
                        ("email", "TEXT"),
                        ("assigned_units", "TEXT DEFAULT '[]'"),
                        ("notes", "TEXT"),
                        ("daily_wage", "REAL DEFAULT 0"),
                        ("unit_rate", "REAL DEFAULT 0"),
                    ):
                        if column not in existing_columns:
                            conn.execute(f'ALTER TABLE "subcontractors" ADD COLUMN "{column}" {ddl}')
                    conn.commit()
                columns = table_columns(conn, table)
                if table == "personnel" and action != "delete" and personnel_new_password:
                    from src.utils.password_security import hash_password, validate_new_password

                    password_error = validate_new_password(personnel_new_password)
                    if password_error:
                        return self.send_json({"error": password_error}, 400)
                    if "password_hash" not in columns:
                        return self.send_json({"error": "Personnel password storage is unavailable."}, 400)
                    body["password_hash"] = hash_password(personnel_new_password)
